let z = x * y;

---

let x = 10n;
let y = 5;
let z = x + y; // ❌ TypeError

---

let x = 10n;
let y = 5;
let z = Number(x) + y;

---

// Create a BigInt
let largeNumber = BigInt("12345678901234567890");
// Conversions
let num = Number(largeNumber);

---

let x = 1.5n; // ❌ TypeError

---

